Here's a simple React component that will achieve this functionality:

```jsx
import React, { useState } from 'react';

const EditableText = ({ text, onChange }) => {
  const [isEditing, setIsEditing] = useState(false);
  const [value, setValue] = useState(text);

  const handleEditClick = () => {
    setIsEditing(true);
  };

  const handleInputChange = (e) => {
    setValue(e.target.value);
  };

  const handleInputBlur = () => {
    setIsEditing(false);
    onChange(value);
  };

  return (
    <div>
      {isEditing ? (
        <input
          type="text"
          value={value}
          onChange={handleInputChange}
          onBlur={handleInputBlur}
        />
      ) : (
        <span>{value}</span>
      )}

      <button onClick={handleEditClick} disabled={isEditing}>
        Edit
      </button>
    </div>
  );
};

export default EditableText;
```

To use this component, simply import it and pass the initial text value and an onChange handler as props:

```jsx
import React from 'react';
import EditableText from './EditableText';

const App = () => {
  const handleChange = (newValue) => {
    console.log('Value changed to:', newValue);
  };

  return (
    <div>
      <EditableText text="Initial Text" onChange={handleChange} />
    </div>
  );
};

export default App;
```

This component will display the text value and an edit button. When the edit button is clicked, the text turns into an input box. When the input box loses focus (onBlur event), it calls the provided onChange handler and goes back to displaying the text.

