import React from 'react';
import { XYPlot, RectSeries, XAxis, YAxis } from 'react-vis';

const data = [
  { x0: 2, x: 4, y: 0 },
  { x0: 6, x: 8, y: 0 },
];

const shadedRegionStyle = {
  opacity: 0.5,
  fill: 'blue',
};

